# HELPER\n\"\"\"\nobservability_models.py\nLocal request, response and normalization helpers for Managed Metrics Monitoring.\n\"\"\"\n\nfrom typing import List, Dict, Any\n\n# Request models\n\ndef build_query_request(metric: str, start: str, end: str, page_size: int = 1000) -> Dict[str, Any]:\n    \"\"\"Create a request payload for a time‑window query.\n    \"\"\"\n    return {\n        \"metric\": {\n            \"type\": metric,\n        },\n        \"resource\": {\n            \"type\": \"global\",\n        },\n        \"interval\": {\n            \"startTime\": start,\n            \"endTime\": end,\n        },\n        \"aggregation\": {\n            \"alignmentPeriod\": \"60s\",\n            \"perSeriesAligner\": \"ALIGN_MEAN\",\n        },\n        \"pageSize\": page_size,\n    }\n\n# Normalized response models\n\nclass MetricDataPoint:\n    def __init__(self, timestamp: str, value: float):\n        self.timestamp = timestamp\n        self.value = value\n\nclass MetricStatistic:\n    def __init__(self, sum: float, avg: float, min: float, max: float, count: int):\n        self.sum = sum\n        self.avg = avg\n        self.min = min\n        self.max = max\n        self.count = count\n\n# Helper to normalise raw provider response into MetricDataPoint list\ndef normalize_query_response(raw: Any) -> List[MetricDataPoint]:\n    normalized = []\n    for point in raw.get(\"points\", []):\n        normalized.append(MetricDataPoint(point[\"interval\"][\"startTime\"], point[\"value\"][\"doubleValue\"]))\n    return normalized\n\n# Helper to normalise aggregated stats\ndef normalize_stats_response(raw: Dict[str, Any]) -> MetricStatistic:\n    return MetricStatistic(\n        sum=raw.get(\"sum\", 0.0),\n        avg=raw.get(\"avg\", 0.0),\n        min=raw.get(\"min\", 0.0),\n        max=raw.get(\"max\", 0.0),\n        count=raw.get(\"count\", 0),\n    )
